name: deploy

on:
  push:
    branches: [main]
  workflow_dispatch:

concurrency:
  group: smoke
  cancel-in-progress: true

permissions:
  contents: read

jobs:
  smoke:
    runs-on: ubuntu-latest
    timeout-minutes: 30
    env:
      CF_ACCESS_CLIENT_ID: ${{ secrets.CF_ACCESS_CLIENT_ID }}
      CF_ACCESS_CLIENT_SECRET: ${{ secrets.CF_ACCESS_CLIENT_SECRET }}
    steps:
      - uses: actions/checkout@v5
      - uses: actions/setup-node@v5
        with:
          node-version: 24
          cache: npm
      - run: npm ci
      - run: npx playwright install --with-deps chromium-headless-shell
      - name: Wait for Workers Builds to serve this commit
        run: npm run wait:live -- "$GITHUB_SHA"
      - name: Smoke through Access
        run: npm run smoke -- "https://stallion.matthijs-f49.workers.dev/b/ci-${{ github.run_id }}"
import { spawnSync } from "node:child_process";
import { readFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

if (process.env.WORKERS_CI !== "1") {
  console.error(
    "npm run deploy runs only inside Cloudflare Workers Builds; push to main to deploy",
  );
  process.exit(1);
}

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const vars = JSON.parse(readFileSync(join(root, "infra", "access.json"), "utf8"));
const value = (name) => {
  if (!vars[name]) {
    console.error(`infra/access.json has no ${name}; run npm run infra:apply`);
    process.exit(1);
  }
  return vars[name];
};

const run = spawnSync(
  "npx",
  [
    "wrangler",
    "deploy",
    "--var",
    `ACCESS_TEAM_DOMAIN:${value("ACCESS_TEAM_DOMAIN")}`,
    "--var",
    `ACCESS_AUD:${value("ACCESS_AUD")}`,
  ],
  { cwd: root, stdio: "inherit" },
);
if (run.error) throw run.error;
process.exit(run.status ?? 1);
import { accessHeaders } from "./env.mjs";

const [commit, origin = "https://stallion.matthijs-f49.workers.dev"] = process.argv.slice(2);
if (!commit) {
  console.error("usage: node npm-scripts/wait-live.mjs <commit sha> [origin]");
  process.exit(2);
}

const TIMEOUT_MS = 15 * 60_000;
const INTERVAL_MS = 20_000;
const probe = new URL("/api/me/boards", origin);
const deadline = Date.now() + TIMEOUT_MS;
let live = "";

while (Date.now() < deadline) {
  const response = await fetch(probe, { headers: accessHeaders(), redirect: "manual" }).catch(
    (error) => {
      console.log(`${probe} failed: ${error.message}`);
      return undefined;
    },
  );
  live = response?.headers.get("x-stallion-commit") ?? "";
  if (live === commit) {
    console.log(`${origin} serves ${commit}`);
    process.exit(0);
  }
  console.log(
    `${origin} serves ${live || "no x-stallion-commit"} (status ${response?.status}); waiting for ${commit}`,
  );
  await new Promise((resolve) => setTimeout(resolve, INTERVAL_MS));
}

console.error(
  `${origin} still serves ${live || "no x-stallion-commit"} after 15 minutes, not ${commit}; check the Workers Builds log for the stallion Worker`,
);
process.exit(1);
import { existsSync, readFileSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";

export const CONFIG_DIR = join(homedir(), ".config", "stallion");
export const CF_ENV = join(CONFIG_DIR, "cf-env");
export const ACCESS_ENV = join(CONFIG_DIR, "access-env");
export const TFSTATE = join(CONFIG_DIR, "terraform.tfstate");
export const TOFU_INIT = [
  "init",
  "-input=false",
  "-reconfigure",
  `-backend-config=path=${TFSTATE}`,
];

export const parseEnv = (text) =>
  Object.fromEntries(
    text
      .split("\n")
      .map((line) => line.replace(/^\s*export\s+/, "").trim())
      .filter((line) => line && !line.startsWith("#") && line.includes("="))
      .map((line) => {
        const at = line.indexOf("=");
        return [line.slice(0, at), line.slice(at + 1).replace(/^(["'])(.*)\1$/, "$2")];
      }),
  );

export const readEnvFile = (path) => (existsSync(path) ? parseEnv(readFileSync(path, "utf8")) : {});

export const accessHeaders = () => {
  const file = readEnvFile(ACCESS_ENV);
  const id = process.env.CF_ACCESS_CLIENT_ID || file.CF_ACCESS_CLIENT_ID;
  const secret = process.env.CF_ACCESS_CLIENT_SECRET || file.CF_ACCESS_CLIENT_SECRET;
  if (!id || !secret) return {};
  return { "CF-Access-Client-Id": id, "CF-Access-Client-Secret": secret };
};
import { spawnSync } from "node:child_process";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { writeAccessVars } from "./access-vars.mjs";
import { CF_ENV, readEnvFile, TOFU_INIT } from "./env.mjs";

const infraDir = join(dirname(fileURLToPath(import.meta.url)), "..", "infra");
const [command, ...args] = process.argv.slice(2);

if (command !== "plan" && command !== "apply") {
  console.error("usage: node npm-scripts/infra.mjs <plan|apply> [tofu args]");
  process.exit(2);
}

const fileEnv = readEnvFile(CF_ENV);
if (!fileEnv.CLOUDFLARE_API_TOKEN) {
  console.error(`${CF_ENV} does not set CLOUDFLARE_API_TOKEN`);
  process.exit(1);
}

const env = { ...process.env, CLOUDFLARE_API_TOKEN: fileEnv.CLOUDFLARE_API_TOKEN };
const tofu = (...tofuArgs) => {
  const run = spawnSync("tofu", tofuArgs, { cwd: infraDir, env, stdio: "inherit" });
  if (run.error) throw run.error;
  if (run.status !== 0) process.exit(run.status ?? 1);
};

tofu(...TOFU_INIT);
tofu(command, "-input=false", ...args);
if (command === "apply") writeAccessVars(env);
